#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
# Concurrency runqueue wait and CPU PSI may be generated by the benchmark itself.
# The concurrency runner must not post-select cases on those measurements.
! rg -q "concurrency_scrub_case_pressure" "$ROOT/scripts/concurrency-runner-common.sh"
! rg -q "concurrency_scrub_case_pressure" "$ROOT/scripts/run-kv-concurrency-plan.sh"
! rg -q "concurrency_scrub_case_pressure" "$ROOT/scripts/run-kv-concurrency-matrix.sh"
! rg -q "concurrency_scrub_case_pressure" "$ROOT/scripts/run-record-concurrency-plan.sh"
! rg -q "concurrency_scrub_case_pressure" "$ROOT/scripts/run-record-concurrency-matrix.sh"
echo concurrency-runner-common-ok
